use std :: collections :: BTreeSet ; use std :: fmt :: { Display , Formatter } ; use schemars :: JsonSchema ; use serde :: { Deserialize , Serialize } ; use super :: operation :: PermissionOperation ; use super :: policy :: Policy ; use super :: types :: Permission ; use crate :: Rule ; use std :: path :: PathBuf ; use pretty_assertions :: assert_eq ; use super :: * ; use crate :: { Permission , PermissionOperation , Policy , Rule , WriteRule } ; use crate :: policies :: { Permission , Policy , PolicyConfig , Rule } ; impl PolicyConfig { # [doc = " Create a new empty policies collection"] pub fn new () -> Self { Self { policies : BTreeSet :: new () } } # [doc = " Add a policy to the collection"] pub fn add_policy (mut self , policy : Policy) -> Self { self . policies . insert (policy) ; self } # [doc = " Evaluate all policies against an operation"] # [doc = " Returns permission results for debugging policy decisions"] pub fn eval (& self , operation : & PermissionOperation) -> Vec < Option < Permission > > { self . policies . iter () . map (| policy | policy . eval (operation)) . collect () } # [doc = " Find all matching rules across all policies"] pub fn find_rules (& self , operation : & PermissionOperation) -> Vec < & Rule > { self . policies . iter () . flat_map (| policy | policy . find_rules (operation)) . collect () } }